contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum, address newLog) public payable {
        // Initialize the contract to lock the configuration.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Try to change MinSum after initialization; must revert.
        bool setMinSumReverted;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        // Try to change LogFile after initialization; must revert.
        bool setLogFileReverted;
        c.SetLogFile(newLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogFileReverted = true;
        } else {
            setLogFileReverted = false;
        }

        // After Initialized, configuration setters must revert regardless of inputs.
        assert(setMinSumReverted && setLogFileReverted);
    }

    receive() external payable {}
}

